<script setup lang="ts">
import { computed } from 'vue'
import { RouterLink } from 'vue-router'
import SourceHealth from '@/components/SourceHealth.vue'
import StatusBadge from '@/components/StatusBadge.vue'
import { formatInstant, statusDescription } from '@/domain/dashboard'
import { useDashboardStore } from '@/stores/dashboard'

const store = useDashboardStore()
const snapshot = computed(() => store.snapshot)
const executions = computed(() => snapshot.value?.executions ?? [])
const events = computed(() => snapshot.value?.events ?? [])

function taskName(id: string): string {
  return snapshot.value?.tasks.find((task) => task.id === id)?.name ?? id
}
function timestamp(value?: string): string {
  if (!value) return '时间未知'
  return formatInstant(value, 'short')
}
</script>

<template>
  <div v-if="snapshot" class="page-stack">
    <header class="page-header"><div><p class="eyebrow">执行与平台 · OPERATIONS</p><h1>运行观察</h1><p>核对消息、人工处置与监听服务报告的状态事实。</p></div><span class="read-only-mark"><span aria-hidden="true">◉</span> 只读观察</span></header>
    <section class="operation-summary"><div><span>执行记录</span><strong>{{ executions.length.toString().padStart(2, '0') }}</strong></div><div><span>监听服务</span><strong>{{ snapshot.services.length.toString().padStart(2, '0') }}</strong></div><div><span>最近事件</span><strong>{{ events.length.toString().padStart(2, '0') }}</strong></div><p>失败、超时与数据过期都按观测事实展示；看板不会自动重试或归类根因。</p></section>
    <div class="operations-grid">
      <section class="panel service-panel"><header class="section-heading"><div><p class="eyebrow">消息监听</p><h2>Agent 服务状态</h2></div><span class="panel-meta">{{ snapshot.services.length }} 个服务</span></header><div class="service-list"><article v-for="service in snapshot.services" :key="service.id" class="service-card"><div class="service-card__top"><div><p class="eyebrow">{{ service.role === 'task-agent' ? 'TASK AGENT' : 'CENTRE AGENT' }}</p><h3>{{ service.name }}</h3></div><StatusBadge :status="service.status" context="service" /></div><div class="service-card__facts"><div><span>最近检查</span><strong>{{ timestamp(service.lastCheckAt) }}</strong></div><div><span>订阅范围</span><strong>{{ service.subscription ?? '尚未提供' }}</strong></div><div><span>消费者组</span><strong>{{ service.consumerGroup ?? '尚未提供' }}</strong></div></div><p v-if="service.error" class="service-error">{{ service.error }}</p></article></div></section>
      <section class="panel source-panel"><header class="section-heading"><div><p class="eyebrow">跨领域查询</p><h2>来源可用性</h2></div></header><SourceHealth :sources="snapshot.sources" /><p class="source-footnote">来源状态只说明最近一次可观察到的查询情况，不等同于自动判定故障原因。</p></section>
    </div>
    <section class="panel execution-panel"><header class="section-heading"><div><p class="eyebrow">执行记录</p><h2>已观察到的处理结果</h2></div><span class="panel-meta">不包含服务端未返回的记录</span></header><div v-if="executions.length" class="execution-list"><article v-for="execution in executions" :key="execution.id" class="execution-row"><span class="execution-row__icon" :class="{ 'execution-row__icon--alert': ['failed','result_unknown'].includes(execution.status) }" aria-hidden="true">{{ execution.status === 'result_unknown' ? '?' : execution.status === 'failed' ? '!' : '·' }}</span><div class="execution-row__main"><div class="execution-row__title"><RouterLink :to="`/tasks/${execution.taskId}`">{{ taskName(execution.taskId) }}</RouterLink><StatusBadge :status="execution.status" /></div><p>{{ execution.summary ?? statusDescription(execution.status) }}</p><div v-if="execution.failure" class="failure-fact"><strong>失败事实</strong><span>{{ execution.failure.target }}<template v-if="execution.failure.tool"> · {{ execution.failure.tool }}</template></span><span>{{ execution.failure.summary }}</span><code v-if="execution.failure.idempotencyKey">核对标识：{{ execution.failure.idempotencyKey }}</code><small>{{ timestamp(execution.failure.occurredAt) }}</small></div></div><time :datetime="execution.updatedAt">{{ timestamp(execution.updatedAt) }}</time></article></div><p v-else class="quiet-empty">目前没有可显示的执行记录。</p></section>
    <section class="panel event-panel"><header class="section-heading"><div><p class="eyebrow">消息与处置</p><h2>事件记录</h2></div><span class="panel-meta">重复事件不会被当作新的成功执行</span></header><ol class="event-list"><li v-for="event in events" :key="event.id"><span class="event-list__marker" :class="{ 'event-list__marker--duplicate': event.duplicate, 'event-list__marker--error': event.type === 'mcp_failure' }" aria-hidden="true"></span><div><strong>{{ event.title }}</strong><p v-if="event.duplicate" class="event-caveat">重复投递已被幂等处理；它不表示第二次执行成功。</p><small>{{ event.diagnostic ?? (event.taskId ? `关联任务：${taskName(event.taskId)}` : '平台事件') }}</small></div><time :datetime="event.occurredAt">{{ timestamp(event.occurredAt) }}</time></li></ol></section>
    <footer class="page-footnote"><span>只读观察 · 不自动重试、不补发消息、不改变 offset。</span><span>状态可能延迟，处理前请核验来源与关联标识。</span></footer>
  </div>
</template>

