@media(max-width:560px){.page-header{align-items:flex-start}.page-header h1{font-size:1.9rem}.read-only-mark{font-size:.64rem}.operation-summary{gap:.5rem;padding:.8rem}.operation-summary>div{padding-right:.4rem}.operation-summary strong{font-size:1.2rem}.panel{padding:.95rem}.execution-row{grid-template-columns:1.5rem minmax(0,1fr)}.execution-row>time{grid-column:2}.event-list li{grid-template-columns:.7rem minmax(0,1fr)}.event-list time{grid-column:2}.page-footnote{flex-direction:column}}
